Next, enableReorder with a global drag lock:

```js
let dragLock = null;

function enableReorder(ul){
  ul.addEventListener('pointerdown', (e) => {
    if (dragLock) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    const li = e.target.closest('.disc-item');
    if (!li || !ul.contains(li) || li.parentElement !== ul) return;

    const rect = li.getBoundingClientRect();
    const dx = e.clientX - rect.left;
    const dy = e.clientY - rect.top;
    const startX = e.clientX, startY = e.clientY;
    let ghost = null;
    let started = false;

    const cleanup = () => {
      window.removeEventListener('pointermove', onMove, true);
      window.removeEventListener('pointerup', onUp, true);
      window.removeEventListener('pointercancel', onUp, true);
      document.body.classList.remove('is-dragging');
      li.classList.remove('is-reordering');
      ul.classList.remove('is-reordering');
      dragLock = null;
    };

    const onMove = (ev) => {
      ev.preventDefault();
      if (!started) {
        if (Math.hypot(ev.clientX - startX, ev.clientY - startY) < 6) return;
        started = true;
        dragLock = { cancel };
        ghost = li.cloneNode(true);
        ghost.classList.add('disc-ghost');
        ghost.style.width = rect.width + 'px';
        document.body.appendChild(ghost);
        li.classList.add('is-reordering');
        ul.classList.add('is-reordering');
        document.body.classList.add('is-dragging');
      }
      ghost.style.left = (ev.clientX - dx) + 'px';
      ghost.style.top = (ev.clientY - dy) + 'px';

      const others = Array.from(ul.children).filter(x => x !== li && x.classList.contains('disc-item'));
      let ref = null;
      for (const it of others) {
        const rr = it.getBoundingClientRect();
        if (ev.clientY < rr.top + rr.height / 2) { ref = it; break; }
      }
      if (ref) { if (li.previousElementSibling !== ref) ul.insertBefore(li, ref); }
      else if (li.nextElementSibling) ul.appendChild(li);
    };

    const onUp = (ev) => {
      if (ghost) {
        const lr = li.getBoundingClientRect();
        ghost.style.transition = 'left .16s ease, top .16s ease, opacity .16s ease';
        ghost.style.left = lr.left + 'px';
        ghost.style.top = lr.top + 'px';
        ghost.style.opacity = '0';
        setTimeout(() => ghost.remove(), 180);
      }
      cleanup();
    };

    const cancel = () => { if (ghost) ghost.remove(); cleanup(); };

    window.addEventListener('pointermove', onMove, true);
    window.addEventListener('pointerup', onUp, true);
    window.addEventListener('pointercancel', onUp, true);
  });
}
```

